package com.primehr.performancemanagement.infrastructure;import com.primehr.performancemanagement.domain.PerformancePolicyVersion;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.*;import java.util.*;
public interface PerformancePolicyVersionRepository extends JpaRepository<PerformancePolicyVersion,String>{Optional<PerformancePolicyVersion>findByIdAndAgencyId(String id,String agency);List<PerformancePolicyVersion>findByAgencyIdOrderByCreatedAtDesc(String agency);List<PerformancePolicyVersion>findByAgencyIdAndPolicyIdOrderByDefinitionVersionDesc(String agency,String policy);@Query("select v from PerformancePolicyVersion v where v.agencyId=:agency and v.status='PUBLISHED' and v.effectiveFrom<=:to and (v.effectiveTo is null or v.effectiveTo>=:from)")List<PerformancePolicyVersion>overlapping(@Param("agency")String agency,@Param("from")LocalDate from,@Param("to")LocalDate to);}
